import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-ejercicio42',
  templateUrl: './ejercicio42.component.html',
  styleUrls: ['./ejercicio42.component.css']
})
export class Ejercicio42Component implements OnInit{
  public clientesQueCompraronElProductoMasCaro: string[] = [];

  constructor(private servicioMisCompras: MisComprasService) { }

  ngOnInit(): void {
    this.servicioMisCompras.obtenerCompras().subscribe((compras: MisCompras[]) => {
      this.encontrarProductoMasCaro(compras);
    });
  }



  encontrarProductoMasCaro(compras: MisCompras[]) {
    let precioMaximo = 0;
    let nombreProducto = '';
    compras.forEach(compra => {
      compra.productos.forEach(producto => {
        if (producto.precio > precioMaximo) {
          precioMaximo = producto.precio;
          nombreProducto = producto.nombreProd;
        }
      });
    });

    this.clientesQueCompraronElProductoMasCaro = compras
      .filter(compra => compra.productos.some(p => p.nombreProd === nombreProducto))
      .map(compra => compra.emailUsuario);
  }

}

<div class="container">
  <h2>Clientes que compraron el producto más caro</h2>
  <ul *ngIf="clientesQueCompraronElProductoMasCaro.length > 0; else noData">
    <li *ngFor="let cliente of clientesQueCompraronElProductoMasCaro">
      {{ cliente }}
    </li>
  </ul>
  <ng-template #noData>
    <p>No hay datos disponibles.</p>
  </ng-template>
</div>
